{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_card",
        "agenda_card",
        "draft_card",
        "actions_card"
      ]
    },
    "overview_card": {
      "type": "Card",
      "props": {},
      "children": [
        "overview_header_stack",
        "overview_image",
        "overview_text_1",
        "overview_text_2"
      ]
    },
    "overview_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "overview_icon",
        "overview_title"
      ]
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Alpha-Sync Kickoff Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Software_Engineering_Meeting.jpg/1200px-Software_Engineering_Meeting.jpg"
      },
      "children": []
    },
    "overview_text_1": {
      "type": "Text",
      "props": {
        "text": "A 90-minute strategic alignment session for the 'Alpha-Sync' platform migration."
      },
      "children": []
    },
    "overview_text_2": {
      "type": "Text",
      "props": {
        "text": "This meeting is critical for finalizing the Q4 roadmap and technical implementation boundaries."
      },
      "children": []
    },
    "agenda_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agenda_header_stack",
        "agenda_image",
        "agenda_table"
      ]
    },
    "agenda_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "agenda_icon",
        "agenda_title"
      ]
    },
    "agenda_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/clock.svg"
      },
      "children": []
    },
    "agenda_title": {
      "type": "Text",
      "props": {
        "text": "Kickoff Meeting Agenda",
        "variant": "h2"
      },
      "children": []
    },
    "agenda_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Whiteboard_Strategy.jpg/1200px-Whiteboard_Strategy.jpg"
      },
      "children": []
    },
    "agenda_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time (EST)"
          },
          {
            "key": "session",
            "label": "Session"
          },
          {
            "key": "lead",
            "label": "Lead"
          },
          {
            "key": "duration",
            "label": "Duration"
          }
        ],
        "rows": [
          {
            "time": "09:00 - 09:20",
            "session": "Project Goals & Q4 Roadmap",
            "lead": "Product Owner",
            "duration": "20 Min"
          },
          {
            "time": "09:20 - 09:50",
            "session": "Technical Architecture",
            "lead": "Lead Developer",
            "duration": "30 Min"
          },
          {
            "time": "09:50 - 09:55",
            "session": "Buffer / Transition",
            "lead": "-",
            "duration": "5 Min"
          },
          {
            "time": "09:55 - 10:15",
            "session": "Design & UX Review",
            "lead": "UX Designer",
            "duration": "20 Min"
          },
          {
            "time": "10:15 - 10:25",
            "session": "QA Strategy & Testing",
            "lead": "QA Lead",
            "duration": "10 Min"
          },
          {
            "time": "10:25 - 10:35",
            "session": "Final Q&A Session",
            "lead": "Team",
            "duration": "10 Min"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time",
        "highlightColumns": [
          "session"
        ]
      },
      "children": []
    },
    "draft_card": {
      "type": "Card",
      "props": {},
      "children": [
        "draft_title",
        "email_content_stack"
      ]
    },
    "draft_title": {
      "type": "Text",
      "props": {
        "text": "Calendar Invitation Draft",
        "variant": "h3"
      },
      "children": []
    },
    "email_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email_subject_text",
        "email_body_text"
      ]
    },
    "email_subject_text": {
      "type": "Text",
      "props": {
        "text": "Subject: [Kickoff] Alpha-Sync Platform Migration",
        "variant": "body"
      },
      "children": []
    },
    "email_body_text": {
      "type": "Text",
      "props": {
        "text": "Hi Team, please join us for the Alpha-Sync kickoff. This session is vital to ensure our technical and design efforts align with our Q4 strategic objectives. Your attendance is mandatory for a successful rollout.",
        "variant": "body"
      },
      "children": []
    },
    "actions_card": {
      "type": "Card",
      "props": {},
      "children": [
        "actions_title",
        "actions_stack"
      ]
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "zoom_button",
        "docs_button"
      ]
    },
    "zoom_button": {
      "type": "Button",
      "props": {
        "label": "Join Zoom Meeting"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://zoom.us/j/alphasync-kickoff"
          }
        }
      }
    },
    "docs_button": {
      "type": "Button",
      "props": {
        "label": "View Migration Docs"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://docs.google.com/migration-plan"
          }
        }
      }
    }
  }
}
